using System;
using System.Drawing;
using System.Drawing.Imaging;
using System.IO;
using System.Linq;
using System.Windows.Forms;

namespace DragonCompanion {
public static partial class SelfTests {
 static void TestCs2(string folder){
  Check(Cs2Art.Available("anime")&&Cs2Art.Available("pixel"),"Both character styles include a complete front-facing CS2 pose");
  using(var host=new Form())using(var native=new Cs2RawInput(new Cs2InputState(),()=>false)){native.Enable(host.Handle,true);Check(native.Registered&&native.Error=="","Real Windows Raw Input registration succeeds for keyboard and mouse");native.Enable(host.Handle,false);Check(!native.Registered&&native.Error=="","Windows keyboard and mouse registrations can be removed cleanly");}
  var input=new Cs2InputState();Check(input.Bubble=="","CS2 key bubble is absent with no held keys");input.Key((int)Keys.W,true);input.Key((int)Keys.D,true);input.Key((int)Keys.W,true);Check(input.Bubble=="D"&&input.Down((int)Keys.W),"Key auto-repeat cannot displace the most recently pressed key");input.Key((int)Keys.D,false);Check(input.Bubble=="W","Releasing the latest key reveals an earlier still-held key");input.Key((int)Keys.W,false);Check(input.Bubble=="","Releasing all keys immediately hides the key bubble");
  Check(Cs2InputState.Normalize(0x11,0,0)==(int)Keys.LControlKey&&Cs2InputState.Normalize(0x11,0,2)==(int)Keys.RControlKey&&Cs2InputState.Normalize(0x10,0x36,0)==(int)Keys.RShiftKey,"Raw modifier keys resolve left and right variants from scan codes and E0");
  foreach(int header in new[]{16,24}){var packet=new byte[header+16];BitConverter.GetBytes(1).CopyTo(packet,0);BitConverter.GetBytes((ushort)0x1e).CopyTo(packet,header);BitConverter.GetBytes((ushort)Keys.A).CopyTo(packet,header+6);Check(input.Packet(packet,header)&&input.Bubble=="A","Raw keyboard packet decodes A on "+(header==24?"64":"32")+"-bit layouts");BitConverter.GetBytes((ushort)1).CopyTo(packet,header+2);input.Packet(packet,header);Check(input.Bubble=="","Raw key-up packet clears held A on "+(header==24?"64":"32")+"-bit layouts");}
  var mouse=new byte[48];BitConverter.GetBytes(160).CopyTo(mouse,36);BitConverter.GetBytes(-20).CopyTo(mouse,40);BitConverter.GetBytes((ushort)1).CopyTo(mouse,28);input.Packet(mouse,24);input.Step(.05);Check(input.Yaw>0&&input.MouseX>0&&input.MouseY<0&&input.MouseLeft,"Relative mouse packets drive head yaw, the connected hand and mouse clicking");input.Mouse(-100000,0,2,true);input.Step(.1);Check(input.TargetYaw==-1&&!input.MouseLeft&&input.Yaw>=-1,"Mouse yaw stays bounded and button release is reflected");float yaw=input.TargetYaw;input.Mouse(60000,30000,0,false);Check(input.TargetYaw==yaw,"Absolute tablet coordinates cannot be mistaken for FPS relative movement");Check(!input.Packet(new byte[4],24),"Truncated raw packets are ignored");input.Clear();Check(input.Bubble==""&&input.Yaw==0&&!input.MouseLeft,"Losing focus clears held keys, buttons and head state");
  Check(Cs2Art.Keys.Count(k=>k.Movement)==4&&Cs2Art.Keys.Where(k=>k.Movement).Select(k=>k.Key).OrderBy(x=>x).SequenceEqual(new[]{(int)Keys.A,(int)Keys.D,(int)Keys.S,(int)Keys.W}),"Exactly the physical WASD keycaps receive the translucent purple treatment");Check(Cs2Art.Keys.Select(k=>k.Key).Distinct().Count()==Cs2Art.Keys.Length&&Cs2Art.Keys.Any(k=>k.Key==(int)Keys.Space)&&Cs2Art.Keys.All(k=>k.Key!=(int)Keys.NumPad0),"The half keyboard has distinct physical keys, Space and no number pad");
  var shoulder=Cs2Art.Deform(.7f,.69f,0,new PointF(6,3),new PointF(-30,10));var wrist=Cs2Art.Deform(.85f,.97f,0,new PointF(6,3),new PointF(-30,10));Check(shoulder==PointF.Empty&&wrist.X<-29&&wrist.Y>9,"Arm deformation anchors the shoulders while moving continuous sleeves and wrists");
  using(var solid=new Bitmap(270,249)){using(var g=Graphics.FromImage(solid))g.Clear(Color.White);using(var warped=(Bitmap)typeof(Cs2Art).GetMethod("Warp",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{solid,.8f,new PointF(6,3),new PointF(-26,18)})){bool intact=true;for(int y=70;y<260&&intact;y++)for(int x=90;x<250;x++)if(warped.GetPixel(x,y).A!=255){intact=false;break;}Check(intact,"Non-affine shoulder and wrist bends rasterize without transparent mesh seams");}}
  Check(Cs2Profile.IsSelectedProcess("","cs2","")&&!Cs2Profile.IsSelectedProcess("","csgo","")&&Cs2Profile.IsSelectedProcess(@"C:\Games\cs2.exe","cs2",@"c:\games\CS2.exe")&&!Cs2Profile.IsSelectedProcess(@"C:\Games\cs2.exe","cs2",@"D:\Other\cs2.exe"),"CS2 detection accepts cs2 or the exact selected executable and rejects a different game copy");
  foreach(string style in new[]{"anime","pixel"}){for(int frame=0;frame<24;frame++){input.Clear();if(frame>=3&&frame<15)input.Key((int)(frame<9?Keys.W:Keys.A),true);if(frame>=15&&frame<21)input.Key((int)Keys.Space,true);input.Mouse((int)(Math.Sin(frame*Math.PI/12)*25),0,frame>=10&&frame<14?1:2,true);input.Yaw=input.TargetYaw=(float)Math.Sin(frame*Math.PI/12)*.8f;input.Step(.05);var bounds=Cs2Art.Bounds(360,246,128);using(var preview=new Bitmap(552,512))using(var g=Graphics.FromImage(preview)){g.Clear(Color.FromArgb(247,244,252));g.ScaleTransform(4,4);g.TranslateTransform(5-bounds.X,5-bounds.Y);Cs2Art.Draw(g,360,246,128,style,input,Cs2Art.KeyboardHand(input.LatestKey));preview.Save(Path.Combine(folder,"cs2-"+style+"-"+frame.ToString("00")+".png"),ImageFormat.Png);}}Check(true,"Rendered connected CS2 hand, mouse and head feedback over 24 frames: "+style);}
 }
 static void TestCs2Integration(Controller controller,Dashboard panel,string folder){var flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
  controller.Games.OsuMania.ExePath=Path.Combine(folder,"missing-osu.exe");controller.Games.Cs2.ExePath=Application.ExecutablePath;controller.SelectGameMode("auto");Check(controller.Pet.GameMode&&controller.Pet.GameId=="cs2"&&controller.Games.Selected==controller.Games.Cs2,"Automatic process detection enters CS2 when the selected program starts");
  var osuPosition=controller.Games.OsuMania.SavedPosition;controller.BeginGamePlacement("cs2");var bounds=controller.Pet.GamePlacementBounds();var area=Screen.PrimaryScreen.WorkingArea;var position=LayeredPet.ClampScene(new Point(area.Left+240,area.Top+120),area,bounds);controller.Pet.Location=position;typeof(LayeredPet).GetMethod("Drop",flags).Invoke(controller.Pet,null);Check(controller.Games.Cs2.FixedPosition&&controller.Games.Cs2.SavedPosition==position&&controller.Games.OsuMania.SavedPosition==osuPosition,"CS2 double-button placement saves independently of osu!mania");
  controller.ResetGamePosition("left","cs2");var left=controller.Pet.GameDestination();controller.ResetGamePosition("right","cs2");var right=controller.Pet.GameDestination();Check(left.X<right.X&&left.Y==right.Y,"CS2 left and right corners relocate the scene without reversing mouse and keyboard");
  controller.Games.Cs2.ExePath=Path.Combine(folder,"missing-cs2.exe");controller.RefreshGameMode();Check(!controller.Pet.GameMode,"Closing CS2 restores the normal companion mode");controller.Pet.BeginInitialPlacement();controller.RefreshGameMode();Check(controller.Pet.Positioning&&!controller.Pet.GameMode,"Normal initial-position placement survives game detection polling");var initial=LayeredPet.ClampCharacter(new Point(area.Left+120,area.Top+30),area,controller.Pet.Width,64*controller.Settings.Scale);controller.Pet.Location=initial;typeof(LayeredPet).GetMethod("Drop",flags).Invoke(controller.Pet,null);var saved=Store.Load<Settings>("settings.json");Check(controller.Pet.HasInitialPosition&&saved.InitialX==initial.X&&saved.InitialY==initial.Y&&!controller.Pet.Positioning,"Normal initial position is saved when double-button dragging ends");
  using(var second=new LayeredPet(controller)){Check(second.Location==initial,"A new companion window starts at the custom initial position");}controller.Pet.ResetNormalPosition();Check(!controller.Pet.HasInitialPosition&&controller.Pet.Location==controller.Pet.DefaultNormalPosition(),"Restoring the normal default disables the custom initial position");
  panel.Navigate("game-cs2");Check(FindText(panel,"设置固定位置")!=null&&FindText(panel,"恢复默认位置")!=null&&FindText(panel,"选择游戏程序…")!=null,"CS2 exposes its own executable picker and position settings");panel.Navigate("positions");Check(FindText(panel,"自定义初始位置")!=null&&FindText(panel,"恢复默认初始位置")!=null,"Companion settings expose custom and default normal initial positions");
 }
}
}
